  'apps.transfer.title': 'Transfer',
  'apps.transfer.desc': 'Einheitliches Download- und Upload-Management. Wiederaufnahme-Fähigkeit für unterbrochene Transfers und geduldiger Modus, der bis zu 30 Tage auf Offline-Peers wartet.',
  'apps.bot.title': 'Bot',
