  'apps.forum.title': 'Forum',
  'apps.forum.desc': 'Thread-Diskussionen organisiert nach Bereichen und Themen. Dauerhafte, durchsuchbare Archive des Gemeinschaftswissens mit Zitaten und Anhängen.',
  'apps.market.title': 'Markt',
  'apps.market.desc': 'Dezentraler Handel mit Shops, Inventar, Bestellungen und verifizierten Bewertungen. Peer-to-Peer-Transaktionen ohne Zahlungsabwickler.',
  'apps.postcards.title': 'Postkarten',
